pub struct InvCell<T> {
    possible_values: Ghost<ISet<T>>,
    pcell: PCell<T>,
    perm_inv: Tracked<LocalInvariant<(ISet<T>, PCell<T>), PointsTo<T>, InvCellPred>>,
}

